use semio_framework_test_fixtures::fixture_text;
use super::*;
use semio_framework_value::{retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement}};
#[derive(semio_framework_value::RetireOwned,Debug,PartialEq)]struct Added<T:RetireOwned>{index:usize,value:T}
fn observe<T>(f:impl FnOnce()->T)->(T,(usize,usize)){let(v,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);(v,(h.requested_bytes,h.released_bytes))}
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096,"indexed original action must fit4KiB: {}",d.copy_bytes);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source<T:RetireOwned+Sync+'static>(v:T)->RetainedCloneSource<T>{let d=RetainedCloneSource::<T>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(v,(),grant(RetirementDemand{copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})).map_err(|(e,..)|e).unwrap().0}
fn close_source<T:RetireOwned+Sync+'static>(s:&mut RetainedCloneSource<T>){while !s.terminal_is_empty(){let g=grant(s.next_close_demands(4096).unwrap());assert!(s.close_step(g).unwrap().progress().fits(g));}}
fn drain<T:RetireOwned>(v:T){let mut c=ControlledRetirement::new(v).map_err(|(e,_)|e).unwrap();while !c.terminal_is_empty(){let g=grant(c.next_demand(4096).unwrap());assert!(c.step(g).unwrap().progress().fits(g));}}
fn strings(v:&serde_json::Value)->Vec<String>{v.as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect()}
fn exercise(row:&serde_json::Value,cut:Option<usize>){observe(||());let mut a=source(strings(&row["authored"]));let mut o=source(strings(&row["original"]));let mut foreign=source(strings(&row["authored"]));let pointers=(a.borrow().get().iter().map(|v|v.as_ptr()).collect::<Vec<_>>(),o.borrow().get().iter().map(|v|v.as_ptr()).collect::<Vec<_>>());let(mut p,heap)=observe(||RetainedIndexedReplacement::<String,Added<String>>::new(|index,value|Added{index,value}));assert_eq!(heap,(0,0));let mut turns=0;while !p.ready()&&cut.is_none_or(|cut|turns<cut){let g=grant(p.demand(a.borrow(),o.borrow(),4096).unwrap());let(step,heap)=observe(||p.advance(a.borrow(),o.borrow(),RetainedCloneGrant{maximum_items:0,..g}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));let moved=if p.phase==5{p.source.as_ref().and_then(|s|s.front().map(|v|v.as_ptr()))}else{None};let before=p.added.as_ref().map_or(0,Vec::len);let(step,heap)=observe(||p.advance(a.borrow(),o.borrow(),g).unwrap());let receipt=step.progress();assert!(receipt.fits(g));assert_eq!(heap.0,receipt.retained_capacity_bytes,"indexed actual allocation receipt");assert_eq!(heap.1,receipt.released_bytes,"indexed actual release receipt");if let Some(pointer)=moved{if p.added.as_ref().map_or(0,Vec::len)>before{assert_eq!(p.added.as_ref().unwrap().last().unwrap().value.as_ptr(),pointer);}}turns+=1;assert!(turns<10000);}if turns>0{assert!(p.demand(foreign.borrow(),o.borrow(),4096).is_err());}if cut.is_none(){let g=grant(p.take_demand().unwrap());let(out,receipt)=p.take(g).unwrap().unwrap();assert!(receipt.fits(g));assert_eq!(out.is_none(),row["expected"].is_null());if let Some(out)=out{assert_eq!(out.removed,(0..o.borrow().get().len()).collect::<Vec<_>>());assert_eq!(out.added.iter().map(|v|(v.index,&v.value)).collect::<Vec<_>>(),a.borrow().get().iter().enumerate().collect::<Vec<_>>());drain(out);}}p.begin_close();while !p.terminal_is_empty(){let g=grant(p.close_demand(4096).unwrap());assert_eq!(p.close_step(RetainedCloneGrant{maximum_items:0,..g}).unwrap().progress(),Default::default());let(step,heap)=observe(||p.close_step(g).unwrap());let receipt=step.progress();assert!(receipt.fits(g));assert_eq!(heap.0,receipt.retained_capacity_bytes);assert_eq!(heap.1,receipt.released_bytes);}assert_eq!(observe(||drop(p)).1,(0,0));assert_eq!((a.borrow().get().iter().map(|v|v.as_ptr()).collect::<Vec<_>>(),o.borrow().get().iter().map(|v|v.as_ptr()).collect::<Vec<_>>()),pointers);close_source(&mut a);close_source(&mut o);close_source(&mut foreign);}
#[test]fn indexed_replacement_original_rows_and_moved_payloads_match_neutral_cases(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/📋️indexed/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap(){exercise(row,None);}}
#[test]fn indexed_replacement_partial_original_deque_and_output_children_close(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/📋️indexed/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap(){for cut in f["cancelCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;exercise(row,Some(cut));}}}
